+    private static void runFaultReadinessSweep() throws Exception {
+        long[] seeds = {-1017L, -1067L, -1022L};
+        int cases = 0;
+        double maximumVerifiedBoundary = 0;
+        for (long seed : seeds) {
+            Rb56Plan plan = Rb56Plan.resolve(seed);
+            for (int ordinal = 0; ordinal < 5; ordinal++) {
+                double boundary = verifyFaultReadinessCase(plan, ordinal);
+                maximumVerifiedBoundary = Math.max(maximumVerifiedBoundary, boundary);
+                cases++;
+            }
+        }
+        check(cases == 15, "all five declared selected faults run for each of the three frozen development seeds");
+        System.out.println("RB56_RDA_READINESS_SWEEP {\"cases\":" + cases +
+            ",\"seeds\":3,\"faultOrdinalsPerSeed\":5,\"maximumVerifiedBoundarySeconds\":" +
+            number(maximumVerifiedBoundary) + ",\"naturalStepSeconds\":0.1,\"maximumNaturalWaitSeconds\":3}");
+    }
+
+    private static double verifyFaultReadinessCase(Rb56Plan plan, int faultOrdinal) throws Exception {
+        CirSim prior = CircuitElm.sim, singleton = CirSim.theSim;
+        String diode = DiodeElm.lastModelName, zener = ZenerElm.lastZenerModelName,
+            transistor = TransistorElm.lastModelName;
+        int flags = MosfetElm.globalFlags;
+        double beta = MosfetElm.lastBeta;
+        NativeMeterCirSim sim = new NativeMeterCirSim();
+        Vector<CircuitElm> original = sim.elmList;
+        Rb56PhysicalOwnerConstruction.Result fixture = null;
+        Throwable failure = null, cleanup = null;
+        boolean disposed = true;
+        String phase = "CONSTRUCTION";
+        double firstReadySeconds = Double.NaN, readingOhms = Double.NaN, testCurrentAmps = Double.NaN;
+        int verifiedBoundarySeconds = 0;
+        boolean poweredHigh = false, sourcesOff = false, freshAtBoundary = false, meterCleanup = false;
+        long started = System.nanoTime();
+        String faultId = Rb56FaultPopulationContractTest.id(plan, faultOrdinal);
+        CircuitElm.sim = sim;
+        try {
+            fixture = Rb56PhysicalOwnerConstruction.buildSelected(plan, new UnqualifiedBehavior(), faultId);
+            GeneratedBoardInstance owner = fixture.owner;
+            check(owner.getFaultBinding() != null && owner.getFaultCandidates().size() == 5 &&
+                owner.getFaultBinding() == owner.getFaultCandidates().get(faultOrdinal).getBinding() &&
+                faultId.equals(owner.getFaultBinding().getFault().getId()),
+                "selected fault is the exact ordinal from the complete five-record current-owner population");
+            check(fixture.runtime.getCapability(Rb56InstrumentAdmissionCapability.ID) instanceof
+                Rb56InstrumentAdmissionCapability,
+                "faulted fixture retains the registered current-owner resistance policy");
+            sim.generatedBoardInstance = owner;
+            sim.elmList = owner.getSimulationElements();
+            sim.boardModificationController = new BoardModificationController(sim, owner);
+            sim.getBoardPowerController().attach(owner.getExternalPowerBindings());
+            fixture.runtime.installRegisteredCapabilities(sim, owner, sim.boardModificationController, 0);
+            sim.a01MeasurementRunning = true;
+
+            phase = "HEALTHY_POWERED_LOW";
+            advance(sim, fixture, .4);
+            check(!owner.getFaultBinding().isApplied() &&
+                !sim.getBoardPowerController().isElectricallyUnpowered() &&
+                owner.getExternalPowerBindings().areAllConnected(),
+                "healthy low-input setup uses the real powered owner before the selected fault is activated");
+
+            phase = "SELECTED_FAULT_APPLIED";
+            GeneratedFaultBinding selected = owner.getFaultBinding();
+            PhysicalPart<?> affected = fixture.runtime.getInstalledPart(
+                selected.getFault().getTargetComponentId());
+            double healthyFaultValue = liveFaultValue(affected);
+            check(affected instanceof GeneratedFaultOwningPart && affected.isOriginal() &&
+                ((GeneratedFaultOwningPart)affected).ownsGeneratedFault(selected) &&
+                PowerDomainContract.finite(healthyFaultValue) && healthyFaultValue > 0 && healthyFaultValue < 1e9 &&
+                (faultOrdinal == 4 || healthyFaultValue == selected.getFault().getHealthyValue()),
+                "selected exact fault starts on its healthy current original physical part");
+            selected.setApplied(true);
+            sim.needAnalyze();
+            advance(sim, fixture, DT);
+            check(selected.isApplied() && fixture.runtime.getInstalledPart(
+                    selected.getFault().getTargetComponentId()) == affected &&
+                liveFaultValue(affected) == 1e9 && healthyFaultValue != liveFaultValue(affected),
+                "selected fault changes the actual installed resistor or relay backing before HIGH/OFF history");
+
+            phase = "POWERED_HIGH";
+            for (String channel : plan.channels())
+                fixture.tail.sensorSources.get(channel).configure(Rb56Plan.SENSOR_HIGH_VOLTS, .25);
+            sim.needAnalyze();
+            advance(sim, fixture, .03);
+            poweredHigh = !sim.getBoardPowerController().isElectricallyUnpowered() &&
+                owner.getExternalPowerBindings().areAllConnected();
+            check(poweredHigh, "powered HIGH command receives a fresh accepted current-owner solver sample");
+
+            PhysicalResistorPart rda = (PhysicalResistorPart)fixture.runtime.getInstalledPart("RDA");
+            CircuitPostMeasurementEndpoint red = boardPadEndpoint(owner, rda, 0);
+            CircuitPostMeasurementEndpoint black = boardPadEndpoint(owner, rda, 1);
+            ActiveMeasurementReadiness poweredReadiness =
+                sim.getActiveMeasurementReadiness(red, black, RESISTANCE);
+            Quiet powered = new Quiet(sim, owner);
+            check(!poweredReadiness.isReady(), "powered RDA pads are unavailable for an in-circuit resistance test");
+            check(Double.isNaN(sim.measureResistance(red, black, RESISTANCE)),
+                "powered rejection does not return a resistance reading or inject a test source");
+            powered.verify(sim, owner);
+
+            phase = "POWER_OFF";
+            sim.getBoardPowerController().setState(BoardPowerState.UNPOWERED);
+            fixture.runtime.onBoardPowerStateChanged(BoardPowerState.UNPOWERED);
+            sim.needAnalyze();
+            sourcesOff = sim.getBoardPowerController().isElectricallyUnpowered() &&
+                owner.getExternalPowerBindings().areAllDisconnected();
+            check(sourcesOff, "all controllable external power sources are isolated before natural discharge");
+
+            phase = "NATURAL_READINESS_SWEEP";
+            int tick = 0;
+            int firstReadyTick = -1;
+            while (tick < 30 && firstReadyTick < 0) {
+                advance(sim, fixture, .1);
+                tick++;
+                check(sim.generatedBoardInstance == owner &&
+                    sim.getBoardPowerController().isElectricallyUnpowered() &&
+                    owner.getExternalPowerBindings().areAllDisconnected(),
+                    "natural readiness sample retains the same owner with every external power source OFF");
+                ActiveMeasurementReadiness readiness =
+                    sim.getActiveMeasurementReadiness(red, black, RESISTANCE);
+                if (readiness.isReady()) {
+                    firstReadyTick = tick;
+                    firstReadySeconds = tick / 10.0;
+                } else {
+                    verifyUnreadyResistanceRefusal(sim, owner, red, black);
+                }
+            }
+            check(firstReadyTick > 0, "RDA resistance readiness becomes READY within the natural three-second bound");
+            int boundaryTick = Math.min((firstReadyTick / 10 + 1) * 10, 30);
+            check(boundaryTick <= 30,
+                "first READY has a subsequent whole-second verification boundary within the unchanged three-second bound");
+            verifiedBoundarySeconds = boundaryTick / 10;
+            while (tick < boundaryTick) {
+                advance(sim, fixture, .1);
+                tick++;
+                check(sim.generatedBoardInstance == owner &&
+                    sim.getBoardPowerController().isElectricallyUnpowered() &&
+                    owner.getExternalPowerBindings().areAllDisconnected(),
+                    "whole-boundary wait retains the same owner with every external power source OFF");
+                ActiveMeasurementReadiness readiness =
+                    sim.getActiveMeasurementReadiness(red, black, RESISTANCE);
+                if (!readiness.isReady()) verifyUnreadyResistanceRefusal(sim, owner, red, black);
+            }
+            check(tick == boundaryTick &&
+                sim.getActiveMeasurementReadiness(red, black, RESISTANCE).isReady(),
+                "fresh readiness remains READY at the next whole-second natural-time boundary");
+            freshAtBoundary = sim.solverExecutor.isCurrent(sim.solverExecutor.observation(owner), owner);
+            check(freshAtBoundary && sourcesOff && sim.generatedBoardInstance == owner,
+                "whole-boundary proof uses the same current owner, fresh receipt and isolated sources");
+
+            phase = "REAL_RESISTANCE_TRANSACTION";
+            Vector<CircuitElm> graph = new Vector<CircuitElm>(sim.elmList);
+            double before = sim.t;
+            readingOhms = sim.measureResistance(red, black, RESISTANCE);
+            testCurrentAmps = Math.abs(sim.getLastResistanceTestCurrentForDeveloperVerification());
+            meterCleanup = PowerDomainContract.finite(readingOhms) && readingOhms >= 0 &&
+                PowerDomainContract.finite(testCurrentAmps) && testCurrentAmps > 0 && sim.t > before &&
+                sim.elmList.equals(graph) && !sim.activeMeasurementOverlay &&
+                sim.isActiveMeasurementSolverRestoredForDeveloperVerification() &&
+                sim.hasElectricallyNeutralResistanceReferenceForDeveloperVerification();
+            check(meterCleanup, "actual CircuitJS resistance transaction returns a reading and removes/restores its temporary network");
+            check(sim.getBoardPowerController().isElectricallyUnpowered() &&
+                owner.getExternalPowerBindings().areAllDisconnected() && sim.generatedBoardInstance == owner,
+                "accepted resistance transaction leaves the same owner electrically OFF");
+            GeneratedRuntimeInvariant.verify(owner, sim.boardModificationController, sim.elmList);
+            advance(sim, fixture, DT);
+            check(sim.solverExecutor.isCurrent(sim.solverExecutor.observation(owner), owner) &&
+                sim.getBoardPowerController().isElectricallyUnpowered(),
+                "post-transaction owner receipt is refreshed without repowering or replacing the graph");
+            phase = "PASS";
+        } catch (RuntimeException error) {
+            failure = error;
+            throw error;
+        } catch (Error error) {
+            failure = error;
+            throw error;
+        } catch (Exception error) {
+            failure = error;
+            throw error;
+        } finally {
+            boolean overlayClear = !sim.activeMeasurementOverlay;
+            try {
+                sim.a01MeasurementRunning = false;
+                sim.elmList = original;
+                sim.generatedBoardInstance = null;
+                sim.boardModificationController = null;
+                try { sim.solverExecutor.retire(); sim.solverExecutor.invalidate(); }
+                catch (RuntimeException error) { cleanup = error; }
+                catch (Error error) { cleanup = error; }
+                sim.circuitMatrix = null;
+                sim.getBoardPowerController().detach();
+                if (fixture != null) for (CircuitElm element : fixture.owner.getSimulationElements()) try {
+                    element.delete();
+                } catch (RuntimeException error) {
+                    disposed = false;
+                    if (cleanup == null) cleanup = error; else cleanup.addSuppressed(error);
+                } catch (Error error) {
+                    disposed = false;
+                    if (cleanup == null) cleanup = error; else cleanup.addSuppressed(error);
+                }
+            } finally {
+                DiodeElm.lastModelName = diode;
+                ZenerElm.lastZenerModelName = zener;
+                TransistorElm.lastModelName = transistor;
+                MosfetElm.globalFlags = flags;
+                MosfetElm.lastBeta = beta;
+                CircuitElm.sim = prior;
+                CirSim.theSim = singleton;
+            }
+            boolean clean = cleanup == null && disposed && overlayClear && original.isEmpty() &&
+                sim.elmList == original && sim.generatedBoardInstance == null &&
+                sim.boardModificationController == null && sim.circuitMatrix == null &&
+                !sim.solverExecutor.isUnavailable() && CircuitElm.sim == prior && CirSim.theSim == singleton;
+            String status = failure == null && clean ? "PASS" : "FAIL";
+            System.out.println("RB56_RDA_OFF_READINESS {\"seed\":\"" + plan.seed +
+                "\",\"faultOrdinal\":" + faultOrdinal + " ,\"faultClass\":\"" +
+                (faultOrdinal < 4 ? "RESISTOR_VALUE" : "RELAY_COIL") +
+                "\",\"firstReadySeconds\":" + number(firstReadySeconds) +
+                ",\"verifiedWholeBoundarySeconds\":" +
+                (verifiedBoundarySeconds == 0 ? "null" : Integer.toString(verifiedBoundarySeconds)) +
+                ",\"readingOhms\":" + number(readingOhms) + ",\"testCurrentAmps\":" +
+                number(testCurrentAmps) + ",\"poweredHigh\":" + poweredHigh +
+                ",\"sourcesOff\":" + sourcesOff + ",\"freshBoundaryReceipt\":" + freshAtBoundary +
+                ",\"meterCleanup\":" + meterCleanup + ",\"candidateDisposed\":" + disposed +
+                ",\"clean\":" + clean + ",\"phase\":\"" + phase + "\",\"elapsedSeconds\":" +
+                number((System.nanoTime() - started) / 1e9) + ",\"status\":\"" + status + "\"}");
+            if (failure != null) {
+                if (cleanup != null) failure.addSuppressed(cleanup);
+                if (!clean) failure.addSuppressed(new AssertionError("Faulted RDA readiness fixture cleanup failed"));
+            } else if (!clean) throw new AssertionError("Faulted RDA readiness fixture cleanup failed", cleanup);
+        }
+        return verifiedBoundarySeconds;
+    }
+
+    private static double liveFaultValue(PhysicalPart<?> part) {
+        if (part instanceof PhysicalResistorPart)
+            return ((PhysicalResistorPart)part).getElement().getResistance();
+        if (part instanceof PhysicalRelayPart) return ((PhysicalRelayPart)part).getElement().coilR;
+        return Double.NaN;
+    }
+
+    private static void verifyUnreadyResistanceRefusal(NativeMeterCirSim sim,
+            GeneratedBoardInstance owner, CircuitPostMeasurementEndpoint red,
+            CircuitPostMeasurementEndpoint black) throws Exception {
+        Quiet unready = new Quiet(sim, owner);
+        check(Double.isNaN(sim.measureResistance(red, black, RESISTANCE)),
+            "unready OFF measurement refuses without injecting a meter source");
+        unready.verify(sim, owner);
+    }
